create or replace function public.claim_integration_event(p_event_id uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare v_status text; v_claimed timestamptz; begin select status,claimed_at into v_status,v_claimed from public.integration_events where id=p_event_id for update; if not found then return false; end if; if v_status in ('processing') and (v_claimed is null or v_claimed > now()-interval '10 minutes') then return false; end if; if v_status not in ('pending','retry','received','processing') then return false; end if; update public.integration_events set status='processing',claimed_at=now(),claim_attempt=coalesce(claim_attempt,0)+1,retry_count=case when v_status='retry' then coalesce(retry_count,0)+1 else coalesce(retry_count,0) end where id=p_event_id; return true; end; $$; revoke execute on function public.claim_integration_event(uuid) from public,anon,authenticated; grant execute on function public.claim_integration_event(uuid) to service_role;